insert into public.local_businesses
  (name, category, address, phone, website, description, logo_url, source, is_claimed, is_active)
values
  ('Aa'' Fired Up', 'services', 'Lerwick, Shetland', '01595 695355', null, 'Aa'' Fired Up is a fun, friendly & relaxing experience for all, from peerie bairns to auld folk. We offer :- Pottery Painting, Build your own Teddy Bear, Life Castings, Clay to Ceramic hand & foot prints, Hand crafted gifts, Refreshments Teas, Coffees & cakes. See Facebook page for example home craft kits or get in touch to have Gemma create something just for you. Packs available for Zoom party distribution (by customer) or home crafting.', 'https://oneshetland.com/business-logos/aa-fired-up.png', 'livinglerwick', false, true),
  ('Anderson & Co', 'services', 'Lerwick, Shetland', '01595 693714', null, 'Anderson & Co is an old established family firm trading in Shetland knitwear, crafts, children&rsquo;s clothes and nursery products. Founded in 1873 by Thomas Anderson, Anderson''s produce an extensive range of classically styled garments for adults and children in genuine Shetland wool renowned for its softness and warmth. They also stock a wide range of accessories including traditional Fair Isles, lightweight lace, seamless Shetland sweaters and chunky hand knitted ski sweaters. Also in stock are spinning wheels, patterns, wool and knitting books', 'https://oneshetland.com/business-logos/anderson-co.png', 'livinglerwick', false, true),
  ('Anderson & Goodlad', 'services', 'Lerwick, Shetland', '01595 692297', null, 'Solicitors, Notary Public & Estate Agents Founded in 1882 by John Bannatyne Anderson, the firm added the name Goodlad when the present Partner&rsquo;s grandfather, the late Peter Goodlad, joined the Firm in the 1930s. As Shetland&rsquo;s longest established Firm, our office has always been located in the heart of Lerwick, first at 58 and now at 52 Commercial Street, Lerwick. Being in the centre of town, banks, building societies and other business organisations are easily accessible. We also provide a ramp for wheel chair and pram access. Legal services we provide to the community:- Adult With Incapacity Law, Crofting Law, Executries, Wills & Trusts, Family Law, Housing Landlord & Tenant, Residential Conveyancing and Estate Agency to name a few.', 'https://oneshetland.com/business-logos/anderson-goodlad.jpg', 'livinglerwick', false, true),
  ('Arch Henderson LLP', 'services', 'Lerwick, Shetland', '01595 695512', null, 'We specialise in Civil and Structural Engineering, Architecture and Environmental Services. We offer a complete and flexible consultancy service, from project conception to project completion.', 'https://oneshetland.com/business-logos/arch-henderson.jpg', 'livinglerwick', false, true),
  ('Arthur and Simpson', 'other', 'Lerwick, Shetland', '01595 747045', null, 'Welcome to Arthur & Simpson Arthur Simpson - Estate and Letting Agents in the Shetland Islands. We take the stress out of selling, renting and managing property for homeowners with our vast experience and professional approach.', 'https://oneshetland.com/business-logos/arthur-and-simpson.jpg', 'livinglerwick', false, true),
  ('Aura Lounge', 'services', 'Lerwick, Shetland', '01595 540220', null, 'Aura Lounge Ltd is a local beauty retreat offering a wide range of beauty treatments in a relaxing and welcoming environment. Whether you&rsquo;re looking to unwind or enjoy a little self-care, Aura Lounge provides professional treatments designed to help you look and feel your best.', 'https://oneshetland.com/business-logos/aura-lounge.jpg', 'livinglerwick', false, true),
  ('Aurora', 'retail', 'Lerwick, Shetland', '01595 741414', null, 'A full range of Silver, Gold and Diamond Aurora Jewellery is available in our shop. Along with Kilt Hire and Purchase we also stock a large selection of gift items and textiles. Drop by and see us sometime. We look forward to seeing you.', 'https://oneshetland.com/business-logos/aurora.png', 'livinglerwick', false, true),
  ('Avril Thomson Smith Art', 'services', 'Lerwick, Shetland', null, null, 'Shetland artist, born in 1975 on the most northerly island in Scotland, the Shetland Islands, draws inspiration from the local landscape. Having grown up in Lerwick, they loved playing in the lanes as a child and now enjoy drawing them. The different textures and shades, especially of the cobblestones, trees, and steps, captivate them. The way the light changes the atmosphere of the lanes is fascinating, and the history of this special part of Lerwick, along with its stories, intrigues them. They strive to capture the stillness and sense of timelessness in their drawings. Bigton, located at the south end of Shetland, was another favorite childhood haunt. It was home to their grandparents, where they spent many happy days playing in the hay and fields with Shetland ponies, cows, sheep, and playful little lambs. Recently, the artist has returned to their &lsquo;Ness&rsquo; roots to celebrate the islands&rsquo; unique landscape. Their latest collections include paintings of abandoned ''yoals'' (rowing boats), old croft houses, wildlife, and Shetland&rsquo;s beautiful wildflowers.', 'https://oneshetland.com/business-logos/avril-thomson-smith-art.jpg', 'livinglerwick', false, true),
  ('Babs Clubb Studio & Shetland Academy of Beauty', 'services', 'Lerwick, Shetland', '07760 168830', null, 'Bab''s Clubb is a seasoned professional make up artist with a wealth of experience and extensive training. Having completed a rigorous 2-year program at West College Scotland in Glasgow, including an HNC in Fashion Makeup and HND in Make-Up Artistry, they possess a comprehensive skill set across various domains of the industry. Their training covered a wide spectrum of specialties, ranging from bridal and event makeup to television and film, stage and theatre, airbrushing, commercial and editorial work, runway and period makeup, as well as face and body painting, special effects, and prosthetic applications. With a diverse background, they have lent their expertise to theatre and stage productions, events, films, and even worked with the BBC on TV dramas and quiz shows. Their approach to each project is marked by confidence and creativity, ensuring exceptional results across different genres of the industry. In addition to their work as a makeup artist, they have also served as a lecturer at West College Scotland, imparting their knowledge and skills to aspiring makeup artists. More recently, they have taken on the role of an adult learning tutor, furthering their commitment to sharing their passion and expertise. With over 20 years of experience under their belt, coupled with extensive product knowledge and boundless enthusiasm, they continue to make their mark in the world of makeup artistry. Bab''s also is the owner of Shetland Academy of Beauty - the ultimate destination for all things makeup and beauty! The academy offers a comprehensive range of courses and qualifications tailored to equip individuals with the skills and knowledge necessary to excel in the industry. The academy firmly believes in the importance of being qualified for any aspiring makeup artist or beautician, as it not only showcases expertise and professionalism but also ensures the delivery of safe and high-quality treatments. With a hands-on approach and personalized guidance, the academy is dedicated to supporting individuals in achieving their goals and realising their full potential as makeup artists or beauty therapists. Join our community of beauty enthusiasts today and embark on a journey towards success!', 'https://oneshetland.com/business-logos/babs-club-studio.jpg', 'livinglerwick', false, true),
  ('Bank of Scotland', 'services', 'Lerwick, Shetland', '07772368844', null, 'Lerwick branch of the Llyods Banking Group, trading as Bank of Scotland.', 'https://oneshetland.com/business-logos/the-lloyds-banking-group.jpg', 'livinglerwick', false, true),
  ('Beauty Services at 7 Reform Lane', 'services', 'Lerwick, Shetland', '01595 694496', null, 'Health and Beauty: Irene is HND trained with over 33 years experience as an Intense Pulsed Light (IPL) therapist, and also offers skin rejuvenation, electrolysis and advanced electrolysis. Book an appointment for a consultation or treatment on 01595 694496. Jade Keenan Aesthetics: Jade is a NVQ Level 2 and 3 trained beauty therapist offering a range of services from the salon: IPL, skin rejuvenation, carbon facials, electrolysis, LVL lash lift and waxing. Call for an appointment &ndash; 07722 182310 or email for more details: jadekeenanaethetics@gmail.com Services Offered: Hair Removal Lash and Brow Treatments Manicures, pedicures, and other nail services to keep your hands and feet looking their best.', 'https://oneshetland.com/business-logos/health-beauty.jpg', 'livinglerwick', false, true),
  ('Beauty109', 'services', 'Lerwick, Shetland', null, null, 'Beauty109 offers a luxurious range of beauty treatments, providing clients with professional and personalised care in a relaxing environment. Conveniently located in the central town area. Their services include: Builder Gel Manicure: For clients looking for long-lasting strength and style, this durable manicure ensures a flawless finish. Hybrid Lash Extensions: A perfect combination of classic and volume lashes, these extensions offer a natural yet voluminous look. Million Dollar Dermaplaning Facial: This rejuvenating facial treatment removes dead skin cells and peach fuzz, leaving skin radiant and smooth. Lash Lift and Tint: A popular treatment that enhances natural lashes with a lift and tint, providing a fresh, wide-eyed appearance. Eyebrow Wax and Brow Sculpt: Tailored to each client, these precision brow treatments result in perfectly shaped brows to complement their facial features. Gel Extensions: Offering beautiful, long-lasting nails, gel extensions are ideal for those wanting added length and elegance. In addition to these services, Beauty at 109 provides a variety of other beauty treatments to meet the diverse needs of their clientele. Located in the town centre, BEauty at 109 invites clients to experience their high-quality beauty services. Book an appointment today and discover the ultimate in beauty care.', 'https://oneshetland.com/business-logos/beauty-at-109.jpg', 'livinglerwick', false, true),
  ('Blyde Welcome', 'services', 'Lerwick, Shetland', '07443128787', null, 'Shetland''s foremost training provider for the hospitality and tourism sector, Blyde Welcome can provide vocational or bespoke, hands-on training to match your specific requirements. Blyde Welcome also provide speciality tea''s and Orkney roasted coffee along with a selection of cakes and sandwiches, all made locally.', 'https://oneshetland.com/business-logos/blyde-welcome.jpg', 'livinglerwick', false, true),
  ('BML Accounts Ltd', 'services', 'Lerwick, Shetland', null, null, 'BML Accounts is run by Ben Laurenson, an experienced tax manager with over seventeen years of working in accountancy. A member of the Association of Accounting Technicians and the Association of Tax Technicians, Ben is skilled in tax preparation, private clients, accounting, partnership taxation, and tax accounting. He is also proficient with helping professionals working at sea, and is considered an expert nationally in the field of Seafarer&rsquo;s Earnings Discount (SED). Choosing BML means choosing a client focused service: Ben is committed to providing a service based on trust and transparency, and having worked as an accountant in Shetland for 17 years, is well placed to work closely with local companies.', 'https://oneshetland.com/business-logos/bml-accountants.jpg', 'livinglerwick', false, true),
  ('Boots', 'services', 'Lerwick, Shetland', '01595 692619', null, 'Boots is the UK&rsquo;s leading pharmacy-led health and beauty retailer. With around 2,500 stores ranging from local community pharmacies to large destination health and beauty stores, our purpose is to help our customers look and feel better than they ever thought possible. Boots UK is part of the Retail Pharmacy International Division of Walgreens Boots Alliance, Inc, the first global pharmacy-led health and wellbeing enterprise.', 'https://oneshetland.com/business-logos/boots.jpg', 'livinglerwick', false, true),
  ('Bressay Ferry Waiting Room', 'other', 'Lerwick, Shetland', null, null, 'Waiting area for Bressay ferry passengers, located within Albert Building.', 'https://oneshetland.com/business-logos/bressay-ferry-waiting-room.jpg', 'livinglerwick', false, true),
  ('British Red Cross Society', 'retail', 'Lerwick, Shetland', '01595 693517', null, 'The British Red Cross has been helping millions of people in the UK and around the world get the support they need when crisis strikes. From hiring a wheelchair or dealing with loneliness, to adjusting to life in a new country - we&rsquo;re there when you need us. The Red Cross Charity Shop plays a vital role in raising funds for the Red Cross&rsquo;s humanitarian efforts. This shop offers a diverse array of goods, both new and gently used, ensuring there is something for everyone. What Shoppers Will Find: &bull; Clothing: A wide selection of new and pre-loved men&rsquo;s, women&rsquo;s, and children&rsquo;s apparel. &bull; Books: An assortment of books covering various genres and interests. &bull; Homeware: Unique home d&eacute;cor items to add charm and style to any living space. &bull; Accessories: A range of jewellery, handbags, shoes, and other accessories to complete any outfit. &bull; Toys and Games: A variety of toys and games for children of all ages. Reasons to Visit: &bull; Support Humanitarian Efforts: Purchases contribute directly to funding the Red Cross&rsquo;s vital services and aid programs. &bull; Eco-Friendly Shopping: Buying pre-loved items helps reduce waste and promote sustainability. &bull; Community Engagement: The shop serves as a local hub for those who want to support a worthy cause and connect with their community. Donations: The Red Cross Charity Shop gratefully accepts donations of new and gently used items, including clothing, books, homeware, and more. Contributions help support their ongoing humanitarian work.', 'https://oneshetland.com/business-logos/british-red-cross-society.png', 'livinglerwick', false, true),
  ('Burns Lane Clothing', 'services', 'Lerwick, Shetland', '01595 692388', null, 'Burns Lane Clothing &ndash; it&rsquo;s right up your street Opened in May 2018 Owners Ian Pagulayan and Michael Laurenson decided to expand from their already successful Sports/Outdoor business&rsquo; Cee & Jays and Intersport to fashion retail. Burns Lane Clothing is a new venture into ladies and mens designer clothing, footwear and accessories, providing Commercial Street with affordable current high street trends with a unique individual feel. Keen to work with brands such as Selected Femme/Homme that are committed to making their collections as sustainable as possible to help save our environment. Burns Lane Clothing also welcomes local designers from around Shetland to sell their products instore to support their creativity and businesses. Proud to stock &ndash; Drummie Bee, HM Textiles, Angela Irvine and Sew Knot Knitted.', 'https://oneshetland.com/business-logos/burns-lane-clothing.png', 'livinglerwick', false, true),
  ('C''est La Vie', 'services', 'Lerwick, Shetland', '01595 697154', null, 'Welcome to C''est la Vie &ndash; A Taste of France in the Heart of Lerwick Nestled in the centre of Lerwick, Shetland, C''est la Vie is a French-inspired restaurant that offers an authentic taste of France in a cosy, welcoming setting. Whether for a casual meal or a quick bite, the restaurant&rsquo;s menu is designed to captivate diners with its delicious range of French classics. With a warm and inviting atmosphere, C''est la Vie prides itself on creating a relaxing dining experience. The staff are fluent in English, Spanish, and, of course, French, ensuring every guest feels at home. For those looking to experience a slice of French life in Lerwick, C''est la Vie offers a delightful culinary escape. Book a table today and savour life&rsquo;s simple pleasures &ndash; because after all, C''est la Vie!', 'https://oneshetland.com/business-logos/cest-la-vie.png', 'livinglerwick', false, true),
  ('Camera Centre', 'services', 'Lerwick, Shetland', '01595 694345', null, 'From Canon to Nikon, Apple to Samsung, Camera Centre are your local photographic and mobile experts. Our dedication to service, photographic expertise and excellent customer service is underpinned with our ''Price Promise'' guarantee which means you can buy the very latest digital camera even if you cannot find the product on our website. We are proud to be Britain''s most northerly winners of former BBC Dragons'' Den star The Paphitis'' Small Business Sunday award. Think twice, shop local.', 'https://oneshetland.com/business-logos/camera-centre.png', 'livinglerwick', false, true),
  ('Cancer Research UK', 'services', 'Lerwick, Shetland', '01595 695349', null, 'The Cancer Research Shop in Lerwick Town Centre stands as a beacon of community spirit and charitable endeavour. Located in Harrison Sq, this shop is dedicated to supporting life-saving cancer research through the sale of high-quality, pre-loved items. What Shoppers Will Find: &bull; Clothing: A diverse selection of men''s, women''s, and children''s apparel, ranging from casual wear to formal attire. &bull; Books: A variety of books across all genres, catering to every type of reader. &bull; Homeware: Unique and stylish items designed to enhance any home d&eacute;cor. &bull; Accessories: A range of jewellery, handbags, shoes, and more to complement any outfit. &bull; Toys and Games: Fun and educational toys for children of all ages. Donations: The shop welcomes donations of gently used clothing, books, homeware, and more. These contributions support the mission and enable continued operations.', 'https://oneshetland.com/business-logos/cancer-research-uk.png', 'livinglerwick', false, true),
  ('Caroline Leask - Therapies', 'services', 'Lerwick, Shetland', '07557 979579', null, 'Play Therapy Shetland offers a confidential space for children, teens and adults. Here there are three services available; Counselling, Play Therapy and Parent/Carer Consultations Counselling gives you the opportunity to speak through difficulties that are getting in the way of your daily living, a space to explore the deeper issues, to make sense of them and leave them behind. Play Therapy is an effective therapeutic intervention for children who have emotional or behaviour difficulties. It is an effective way to help children who have attachment difficulties and those who have witnessed traumatic events. Parenting Consultations is a service for parents who are struggling in their role or worried for their children. Play Therapy Shetland is based in Lerwick; I am fully trained as a Person Centred Counsellor and Certified Play Therapist. Also, I am a member of BACP (British Association of Counselling and Psychotherapy) and PTUK (Play Therapy UK). I am on the Accredited Voluntary Register, the professional standards authority register run by the government, which allows the public to monitor counsellors and play therapists. I have over 10 years of experience in counselling and working therapeutically with children. As well as this, I offer supervision for professionals and have trained with APAC/PTUK. For more information please get in touch. keep your eyes peeled for Meditation and Wellness courses, workshops and events.', 'https://oneshetland.com/business-logos/caroline-leask-therapies.jpg', 'livinglerwick', false, true),
  ('CASE Shetland LTD', 'services', 'Lerwick, Shetland', '01595 840476', null, 'CASE Shetland was set up as an alternative to the larger engineering practices which have offices on the isles. There was a growing demand from the private sector for a engineering consultancy which was willing to focus its attention on the residential market, as house building on the isles continued to boom. CASE Shetland appreciates that for the Customer every job is important, no matter what size it may be. Our aim is to deliver a consistently high service right across the board, from small extensions to large new builds. The ethos of the company is to provide added value wherever possible. Managing Director Ewen Adamson gained a Masters Degree in Structural Engineering with Architectural Design therefore understands the importance of integration between the professions. A construction project should not be looked upon from purely an architectural perspective or an engineering one, it should be a collaborative effort. We aim to work with the Architect/Agent from an early stage to ensure that the engineering input enhances the overall project, rather than just being an add on at the end. At CASE Shetland we combine engineering proficiency with design flair. Please get in touch to see what we could add to your project, however large or small.', 'https://oneshetland.com/business-logos/case-shetland-ltd.jpg', 'livinglerwick', false, true),
  ('Cee & Jays', 'retail', 'Lerwick, Shetland', '07315390657', null, 'Shetland Sports & Footwear is a premier retailer located in the heart of Lerwick, specialising in footwear, sports goods, and clothing. Serving the local community with a wide range of high-quality products. What Shoppers Will Find: &bull; Footwear: A vast selection of athletic shoes, casual footwear, and specialty sports shoes for all ages and activities. &bull; Sports Goods: Equipment and accessories for various sports, including football, running, swimming, and more. &bull; Clothing: Performance apparel, casual wear, and activewear for men, women, and children, suitable for both sports and everyday use. &bull; Accessories: Sports bags, socks, hats, and other essential accessories to complement any sporting activity. Opening hours: Monday to Saturday; 9:00am to 5:00pm', 'https://oneshetland.com/business-logos/cee-jays.png', 'livinglerwick', false, true),
  ('Coffee Culture', 'food_drink', 'Lerwick, Shetland', '01595 694376', null, 'A warm welcome from Jigar and his friendly staff awaits at Coffee Culture, a delightful caf&eacute; in the heart of Lerwick. Known for its cozy atmosphere and exceptional service, Coffee Culture is the perfect spot to relax and enjoy a delicious snack. At Coffee Culture you can expect: Beverages: A variety of hot and cold drinks, including expertly brewed coffee, specialty teas, and refreshing juices. Sandwiches & Paninis: A delectable selection of freshly made sandwiches and paninis, prepared with high-quality ingredients. Salads: A diverse salad counter offering healthy and tasty options to suit every preference. Cakes & Desserts: An array of mouth-watering cakes and desserts, perfect for satisfying any sweet tooth. Jigar and his team provide a friendly and inviting environment where everyone feels at home. Download the HOPT app to order online. The HOPT App allows customers to order online and collect when they want.', 'https://oneshetland.com/business-logos/coffee-culture.png', 'livinglerwick', false, true),
  ('Connie Laureen Jewellery', 'services', 'Lerwick, Shetland', null, null, 'Independent handmade jewellery shop located in the heart of Lerwick. This small independent jewellery shop is a real local treasure. Everything is handmade by Connie, with each piece carefully crafted to be completely unique. From subtle everyday jewellery to more eye-catching designs, the collection reflects true skill, creativity, and attention to detail. A go-to for thoughtful gifts, special occasions, or simply treating yourself to something beautifully made and one-of-a-kind.', 'https://oneshetland.com/business-logos/connie-laureen.jpg', 'livinglerwick', false, true),
  ('Conochie''s Newsagent & Post Office', 'services', 'Lerwick, Shetland', '07369805415', null, 'Conochie''s Newsagents, the most popular newsagent in Shetland, is conveniently located in the heart of Lerwick''s town centre. Known for its wide range of products and services, Conochie''s is a one-stop shop for locals and visitors alike. News and Magazines: A comprehensive selection of newspapers and magazines covering various interests and topics. Thornton&rsquo;s Chocolates: An exclusive Thornton&rsquo;s chocolate franchise offering a delightful array of premium chocolates. Cards and Gifts: A great selection of greeting cards for all occasions and unique gifts to suit every taste. Post Office Facilities: Convenient post office services available within the store, making it easy to handle mailing needs.', 'https://oneshetland.com/business-logos/conochies.png', 'livinglerwick', false, true),
  ('CoWork', 'other', 'Lerwick, Shetland', '01595 747200', null, 'CoWork Shetland provides flexible office space in the heart of the capital, Lerwick. Take your business to the next level with your own dedicated desks, private offices or hot desk memberships - perfect for budding freelancers, growing businesses or those needing a town base.', 'https://oneshetland.com/business-logos/cowork.png', 'livinglerwick', false, true),
  ('CU Marketing', 'services', 'Lerwick, Shetland', null, null, 'CU Marketing Ltd. is dedicated to the belief that small local businesses are vital to any community, particularly in island regions such as Orkney and Shetland. Currently, CU Marketing Ltd. supports local small businesses and community organisations through a range of services. In addition to managing various short-term contracts, the company provides financial management for Foula Electricity Trust, an off-grid renewable energy provider on the Isle of Foula. They are also contracted as the Membership Adviser for the Federation of Small Businesses in Orkney and Shetland. Christena Irvine owns CU Marketing Ltd. As a Chartered Marketer with over twenty years of experience, she is passionate about leveraging her expertise to help small businesses, charities, and community organisations thrive.', 'https://oneshetland.com/business-logos/cu-marketing.jpg', 'livinglerwick', false, true),
  ('D.G Leslies', 'retail', 'Lerwick, Shetland', '01595 693073', null, 'DG Leslie is a well-established convenience store, off licence, and tobacconist located in the heart of Lerwick. Known for its diverse offerings and commitment to local products, DG Leslie is a go-to destination for everyday essentials and more. What You''ll Find: A wide range of groceries, household items, and everyday necessities. A selection of local and international wines, beers, and spirits to suit any taste. An assortment of tobacco products and accessories. Fresh and locally sourced produce, supporting local farms and producers. Delicious, freshly made sandwiches from various local supplier in Shetland, perfect for a quick lunch or snack.', 'https://oneshetland.com/business-logos/don-leslies.png', 'livinglerwick', false, true),
  ('Da Harbour Chippy', 'services', 'Lerwick, Shetland', '01595 482024', null, 'Da Harbour Chippy provides tasty and freshly cooked food every time, with friendly service. We have competitive pricing, a convenient Esplanade location and long opening hours, making it easy for you to get good food whenever you want it.', null, 'livinglerwick', false, true),
  ('Eldamato', 'retail', 'Lerwick, Shetland', '07454872131', null, 'Welcome to Eldamato: Your haven for spinning, felting, and local knitwear Located in the centre of Lerwick, just next door to the iconic Peerie Shop, Eldamato is your destination for all things spinning, felting, and locally crafted knitwear. Whether you''re a beginner looking to delve into the world of textile crafts, we have everything you need to unleash your creativity and bring your projects to life.', 'https://oneshetland.com/business-logos/eldamato.jpg', 'livinglerwick', false, true),
  ('Envi', 'services', 'Lerwick, Shetland', '01595 691011', null, 'Envi is a family-run hair salon located centrally at 110 Commercial Street, Lerwick. Conveniently situated near bus routes and with ample nearby parking, Envi is easily accessible for all clients. A skilled and talented team of hairdressers is dedicated to delivering top-quality hair services. Bookable appointments and walk-ins are both available to accommodate various schedules. The salon uses a range of high-quality products, including Matrix, Colour Evo, and L&rsquo;Or&eacute;al. Additionally, clients can purchase products to maintain their hair care routine at home. Catering to all clients with a range of services, including cutting, colouring, styling, blow-drying, and barber services. Additional Treatments: Offering nails, makeup, bridal and occasion hair, and more. For any requests or queries, feel free to send a message, and the team will be delighted to assist. Visit Envi for a personalised and professional hair care experience.', 'https://oneshetland.com/business-logos/envi.png', 'livinglerwick', false, true),
  ('Ferry Terminal', 'other', 'Lerwick, Shetland', null, null, 'Ferry to Bressay https://www.shetland.gov.uk/ferries', 'https://oneshetland.com/business-logos/ferry-terminal.jpg', 'livinglerwick', false, true),
  ('Fort Charlotte Guest House', 'services', 'Lerwick, Shetland', '01595 692140', null, 'Fort Charlotte Guesthouse is a family run guesthouse ideally situated the heart of Lerwick, Shetland Islands. We pride ourselves on our great service, location and hospitality. In the heart of the Lerwick town centre, our guesthouse has restaurants, bars, beaches, transport links and the award winning new museum right on our doorstep, so whether it''s a long weekend, short break, annual holiday or a business trip we have the perfect base for your retreat to the Shetland Islands. The 5 en-suite bedrooms are all beautifully furnished and have generous facilities to make your stay as comfortable as possible. All rooms are centrally heated, have smart TV, hair-dryers, refrigerators stocked with fresh milk & water and refreshment trays replenished daily.', 'https://oneshetland.com/business-logos/fort-charlotte-guest-house.jpg', 'livinglerwick', false, true),
  ('Fort Fish & Chip Shop', 'food_drink', 'Lerwick, Shetland', '01595 693125', null, 'Fort Chippy is a beloved Fish & Chip shop in Lerwick, renowned for serving some of the finest local fish in Shetland. Situated on Commerical Street opposite the Fort, this popular chippy is committed to delivering delicious, freshly prepared meals with a focus on locally sourced seafood.', 'https://oneshetland.com/business-logos/fort-cafe-takeaway.png', 'livinglerwick', false, true),
  ('George Robertson (Shetland) Ltd', 'services', 'Lerwick, Shetland', '01595 692915', null, 'Established in 1947, George Robertson (Shetland) Ltd has been in business for more than 75 years and is proud to be Shetland&rsquo;s leading electrical contractor (GR Contracting), electrical appliance retailer (GR Direct), and kitchen design studio (GR Kitchens). GR Contracting - We provide electrical services within retail, domestic, commercial and industrial sectors, taking great pride in our ability to deliver on projects, no matter how large or small by always ensuring we provide a first-class service from initial contact to the completion and beyond for each project. GR Direct &ndash; We offer a wide range of home electricals at competitive prices; from televisions to fridge freezers, and washing machines to home sound systems. We are trusted dealers of well-known brands such as Bosch, Neff, Siemens, Sony, Sonos, Blomberg, Beko, Dyson, Shark, Rangemaster, Ninja and many more. We have built a reputation for great customer service, competitive pricing, and expertise in sales and aftercare. GR Kitchens &ndash; We provide world-renowned, high-quality kitchens to suit a range of budgets. Our experienced designers can ease you through the whole process - design, supply and installation. Visit our website to find out more about the services and products we offer: www.grdirect.co.uk', 'https://oneshetland.com/business-logos/george-robertson-ltd.png', 'livinglerwick', false, true),
  ('Graceful Beauty', 'services', 'Lerwick, Shetland', '07821 565303', null, 'Grace Allan is a fully qualified Beauty Therapist who has been established in the trade for a number of years and is now opened up her own salon in the centre of Lerwick. She offers a wide range of Beauty Treatments and specialises in Nouveau Eyelash Treatments including Extend, Volume and LVL. Treatments available include: Nouveau Eyelash Enhancements Hand & Foot Treatments Eyelash & Eyebrow Tinting Waxing Swedish and Deep Tissue Massage Graceful Beauty can offer out of salon treatments by special request, this may include a call out fee.', 'https://oneshetland.com/business-logos/graceful-beauty.jpg', 'livinglerwick', false, true),
  ('Grantfield Garage', 'services', 'Lerwick, Shetland', '07048583938', null, 'Visiting and want to hire a car in the Shetland Islands? Our extensive car hire and van hire stock contains the vehicle best suited to your needs. We have Self Drive Cars, Vans, Minibuses, People Carriers and a wide range of Cycles available. All at very competitive rates and, if required, child seats available at no extra costs. Additionally, if you are arriving by air or boat, we can arrange (at no extra charge) for you to collect (or leave) your vehicle at Sumburgh Airport or the Northlink Ferry Terminal.', 'https://oneshetland.com/business-logos/grantfield-garage.jpg', 'livinglerwick', false, true),
  ('Harry''s Department Store', 'services', 'Lerwick, Shetland', '01595 693097', null, 'Harry''s is a friendly, family-run business spread across three floors, offering a diverse range of products to meet all your needs. What You''ll Find: Ground Floor: A delightful selection of gifts and cards. Middle Floor: Household items, lighting, and linens. Top Floor: Toys, bikes, crafts, and nursery products. Visit Harry''s for a warm, welcoming shopping experience and a wide variety of quality items.', 'https://oneshetland.com/business-logos/harrys-department-store.png', 'livinglerwick', false, true),
  ('High Level Music', 'services', 'Lerwick, Shetland', '01595 692618', null, 'High Level Music has been in business for 21 years. They moved into their new shop 5 years ago and the business has gone from strength to strength. You can find lots on offer at High Level Music such as: &bull; Instruments for sale &bull; Instrument repair &bull; Music equipment &bull; Music school If you are visiting Shetland on holiday and haven&rsquo;t brought your instrument with you then don&rsquo;t despair, you can hire a guitar/fiddle or ukulele from High Level Music. If you would like to teach music, then please contact Fiona on 01595 692618 to ask about renting a space at the shop to teach. If learning how to play an instrument is something you are interested in then please contact High Level Music to arrange. Fiona and her team are very knowledgeable about instruments and equipment, if you have seen something you would like to know more about, they may be able to get it into the shop for you.', 'https://oneshetland.com/business-logos/high-level-music.png', 'livinglerwick', false, true),
  ('Highland Fuels Ltd', 'other', 'Lerwick, Shetland', '01595 694348', null, 'Scotland&rsquo;s leading independent fuel distributor. We are committed to providing outstanding, professional customer service and we pride ourselves on our reliable and efficient deliveries to homes and businesses throughout Scotland. Since our business started in 1957 in Inverness, we have expanded and now operate from 12 depots across Scotland, servicing both the domestic and commercial markets. Contact our team on 0800 224 224 to receive free friendly advice and information on all of our products and services.', 'https://oneshetland.com/business-logos/highland-fuels-ltd.jpg', 'livinglerwick', false, true),
  ('Historic Scotland', 'services', 'Lerwick, Shetland', null, null, 'Fort Charlotte overlooks the strategic Sound of Bressay. It was built to defend the sound against Dutch and later French warships. Some sort of fortification was erected here during the first Anglo-Dutch War in 1652, though no trace of it is now visible. During the Second Dutch War in the 1660s a second fort was built, but never finished. The fort was not garrisoned during the Third Dutch War, though the Dutch did land and burn the abandoned barrack block here in 1673.', 'https://oneshetland.com/business-logos/historic-scotland.jpg', 'livinglerwick', false, true),
  ('Icare', 'services', 'Lerwick, Shetland', '01595 693690', null, 'Optometrist based in Lerwick At ICare Shetland we pride ourselves on providing a high quality service and the cornerstone of this service is the eye examination. A sight test is much more than a simple prescription check and it is important to be tested regularly. Using the very latest in eye examination technology we can quickly establish the state of your vision, the health of your eyes and also help with the early identification of a range of more general health conditions.', 'https://oneshetland.com/business-logos/icare.png', 'livinglerwick', false, true),
  ('Independent Finance (Shetland)', 'services', 'Lerwick, Shetland', '01595 690808', null, 'Ian Thomson DipFA Cemap is an Independent Financial Adviser trading as Independent Finance (Shetland)', 'https://oneshetland.com/business-logos/june-lorraine-thomson.jpg', 'livinglerwick', false, true),
  ('Intersport', 'retail', 'Lerwick, Shetland', '01595 694959', null, 'The World''s Leading Sports Retail Brand right on your door step. Guaranteeing satisfaction and support to bring you a worry-free shopping experience. We guarantee expert, personalised advice and service with the best choice in leading brands.', 'https://oneshetland.com/business-logos/intersport.png', 'livinglerwick', false, true),
  ('Island Larder', 'food_drink', 'Lerwick, Shetland', '01595 694324', null, 'We are a small family-owned business committed to using and showcasing the very best of Shetland produce. Since launching Island Larder in 2017 we have revamped and grown the business several times, including overhauling our operation during the Covid-19 pandemic, launching a host of new products including artisan ice-cream and an expanded range of fudge and other confectionary items. We are so passionate about all things Shetland and have always wanted to run an independent business taking advantage of all the fantastic local ingredients that are available right on our doorstep. Island Larder is proud to be marketing and showcasing both of these beloved facets of Shetland culture to the wider world because we simply just love our home islands and want to spread the word about this special place as far and wide as we can. Shetland&rsquo;s capital Lerwick is the home of our premises, in the heart of Lerwick&rsquo;s historic and picturesque town centre, where we produce all of our confectionary items. The building itself, on Commercial Street, is steeped in history and was formerly run as Smiths of Lerwick, a family-run clothing shop for many decades. Both my granny and my husband&rsquo;s granny worked in the store, and we use the same bunker that they served from today, made by hand with all the original dents, scrapes and stories.', 'https://oneshetland.com/business-logos/shetland-fudge-co.png', 'livinglerwick', false, true),
  ('J.G.Rae Shetland', 'retail', 'Lerwick, Shetland', '01595 693686', null, 'Jack Rae trained as a jeweller in Edinburgh and moved to the island of Foula in Shetland in 1945. He later moved to Weisdale on the Shetland mainland and started making Jewellery under the name of Shetland Silvercraft in 1953. After his son, Ken Rae, joined the business he bought over what was then &ldquo;The Gift Shop&rdquo; and started trading under the name of J G Rae Ltd in 1965. Ken Rae managed the business for more than 20 years, and had a break of about 8 years before returning in 2000. He now mainly looks after the manufacturing division &ndash; renamed Shetland Jewellery.', 'https://oneshetland.com/business-logos/john-g-rae-ltd.png', 'livinglerwick', false, true),
  ('Jamiesons of Shetland', 'retail', 'Lerwick, Shetland', '01595 693114', null, 'Jamieson&rsquo;s is a family owned business, which has specialised in wool from the native Shetland sheep for 5 generations. The family are dedicated to the survival of this unique fibre and as each new generation joins the business, this promotion becomes their life&rsquo;s ambition. The business was started in the early 1890&rsquo;s. Set up by Robert Jamieson in Sandness, on the far west coast of the Shetland Isles. From his shop, he bought or exchanged for goods, knitwear from the local crofters. The knitted goods were then sold on to meet the public demand for fashionable Shetland hosiery beyond the island&rsquo;s shores.', 'https://oneshetland.com/business-logos/jamiesons-knitwear.png', 'livinglerwick', false, true),
  ('JLP Internet', 'services', 'Lerwick, Shetland', null, null, 'JLP Internet- Shetland Web Design and Online Services. Here at JLP Internet we help businesses unlock the power of the Internet to reach more customers online and become more efficient. We are proud to work with businesses in Shetland and throughout the UK, offering cost effective web design services to businesses of all sizes - from self employed to multi million pound international companies. Having a website is only one part of a successful online strategy. That&rsquo;s why as well as a full website creation service, we also offer custom software solutions built to fit your needs, managed office 365 to streamline your office and internet marketing and search engine optimisation to promote yourself more effectively online.', 'https://oneshetland.com/business-logos/jlp-internet.jpg', 'livinglerwick', false, true),
  ('Jon Stone Hair', 'services', 'Lerwick, Shetland', '01595 695595', null, 'Looking for a barber or a hairstylist specialised in taking care of your hair in LERWICK, SHETLAND? JON STONE, welcomes you for a unique and unforgettable salon experience. JON STONE offers solutions and the latest trends in haircuts, colour, hair care and styling for a total look', 'https://oneshetland.com/business-logos/jon-stone-hair.png', 'livinglerwick', false, true),
  ('Juice Culture', 'other', 'Lerwick, Shetland', null, null, 'Juices,Smoothies,Bubble Tea,Candy Floss,Popcorn,Waffles and much more...', 'https://oneshetland.com/business-logos/juice-culture.jpg', 'livinglerwick', false, true),
  ('Just Gents Barbers', 'services', 'Lerwick, Shetland', '01595 697426', null, 'Gents Barber shop', 'https://oneshetland.com/business-logos/just-gents.jpg', 'livinglerwick', false, true),
  ('Kool Kutz', 'services', 'Lerwick, Shetland', '01595 694995', null, 'Kool Kutz is a long established, family run business, providing a range of hairdressing services to the Shetland community. Furthermore we provide retail services for both the TIGI and ghd brands. Kebelo hair smoothing system is also available. Our staff are TIGI professionally trained, regularly attending further training to keep up to date with the latest styles, cuts and colours.', 'https://oneshetland.com/business-logos/kool-kutz.jpg', 'livinglerwick', false, true),
  ('Kung Fu Cuisine', 'food_drink', 'Lerwick, Shetland', '01595 693377', null, 'Our Lunch Special Bar is open from 12pm - 2pm where you can pick rice or noodles aswell as a main course in our lunch boxes. Menu Orders available from 11am - 8/9pm', 'https://oneshetland.com/business-logos/kung-fu-cuisine.jpg', 'livinglerwick', false, true),
  ('Lerwick Dental Practice', 'services', 'Lerwick, Shetland', '01595 690625', null, 'NHS and Private dental practice Dentist Mr Apil Timilsina, BDS 2008, MPH, MSc SSCD Master in public Health, University of Salford, Manchester Master in Sedation and Special care dentistry, King College London Miss Krupa Muni, BDS 2013 MPH Master in Applied Public Health, Middlesex University, London', 'https://oneshetland.com/business-logos/lerwick-dental-practice.jpg', 'livinglerwick', false, true),
  ('Lerwick DIY', 'retail', 'Lerwick, Shetland', '01595 695666', null, 'DIY retail shop selling Tools; a wide variety of Hardware and Ironmongery; and Gardening tools and accessories. Also offering a Tool Sharpening Service and a Key Cutting Service.', 'https://oneshetland.com/business-logos/lerwick-diy.png', 'livinglerwick', false, true),
  ('Lerwick Port Authority', 'other', 'Lerwick, Shetland', '01595 692991', null, 'Lerwick Harbour, with modern, versatile facilities for a wide variety of users, is the principal commercial port for Shetland and a key component in the islands&rsquo; economy. At the crossroads of the North Sea and North-east Atlantic, Lerwick Harbour is Britain&rsquo;s &ldquo;Top Port&rdquo; &ndash; the most northerly commercial harbour in the country. With two entrances, the sheltered, deep-water port is open to shipping in all weathers and operates around the clock, handling over 5,000 vessels annually.', 'https://oneshetland.com/business-logos/lerwick-port-authority.jpg', 'livinglerwick', false, true),
  ('LHD (Net Mending) Ltd', 'other', 'Lerwick, Shetland', '01595 693768', null, 'The company began life on 3 April 1900 as Lowestoft Steam Herring Drifters Company Limited, and traded under that name until 1943 when a number of its vessels (all at the time on Admiralty service) were sold to the Boston Group. The remaining vessels were sold to Harold Brabner Jackson and transferred back to the company under its amended name Lowestoft Herring Drifters Limited. The company continued trading under that name until 21 October 1970 when the name was changed to L.H.D Limited. Following the acquisition of the local net manufacturing and repair company D & A Duthie, a new subsidiary company L.H.D Net Mending Limited was set up on 5 May 1969 to continue the net manufacture and repair business and expand the range of supplies and services offered to its customers. L.H.D Net Mending Ltd changed its name to L.H.D Marine Supplies on 27 September 1996.', 'https://oneshetland.com/business-logos/lhd-net-mending-ltd.jpg', 'livinglerwick', false, true),
  ('LHD Custom Clothing', 'services', 'Lerwick, Shetland', '01595 696335', null, 'LHD Custom Clothing design, print and embroider garments providing you with brand corporate clothing or leisure wear to your requirements. LHD supply workplace, clubs and associations, sports teams, schools, fishing boats, festivals, promotional items, Up Helly Aa squads, themed parties and personalised gifts.', 'https://oneshetland.com/business-logos/lhd-custom-clothing.png', 'livinglerwick', false, true),
  ('LHD Ltd', 'other', 'Lerwick, Shetland', '01595 693768', null, 'The company began life on 3 April 1900 as Lowestoft Steam Herring Drifters Company Limited, and traded under that name until 1943 when a number of its vessels (all at the time on Admiralty service) were sold to the Boston Group. The remaining vessels were sold to Harold Brabner Jackson and transferred back to the company under its amended name Lowestoft Herring Drifters Limited. The company continued trading under that name until 21 October 1970 when the name was changed to L.H.D Limited. Following the acquisition of the local net manufacturing and repair company D & A Duthie, a new subsidiary company L.H.D Net Mending Limited was set up on 5 May 1969 to continue the net manufacture and repair business and expand the range of supplies and services offered to its customers. L.H.D Net Mending Ltd changed its name to L.H.D Marine Supplies on 27 September 1996.', 'https://oneshetland.com/business-logos/lhd-ltd.jpg', 'livinglerwick', false, true),
  ('LHD Marine Supplies Ltd', 'services', 'Lerwick, Shetland', '01595 693768', null, 'The company began life on 3 April 1900 as Lowestoft Steam Herring Drifters Company Limited, and traded under that name until 1943 when a number of its vessels (all at the time on Admiralty service) were sold to the Boston Group. The remaining vessels were sold to Harold Brabner Jackson and transferred back to the company under its amended name Lowestoft Herring Drifters Limited. The company continued trading under that name until 21 October 1970 when the name was changed to L.H.D Limited. Following the acquisition of the local net manufacturing and repair company D & A Duthie, a new subsidiary company L.H.D Net Mending Limited was set up on 5 May 1969 to continue the net manufacture and repair business and expand the range of supplies and services offered to its customers. L.H.D Net Mending Ltd changed its name to L.H.D Marine Supplies on 27 September 1996. January 1983 saw the takeover of local electronics company H. Williamson & Sons of Scalloway by L.H.D Limited. Together with four of the company''s previous employees, a new company, H. Williamson & Sons (Scalloway) Limited was formed. The company specialises in the supply and servicing of electronics for the marine, aquaculture and fish processing industries. In 1985, L.H.D Limited took over J & M Shearers and formed a new company J & M Shearers (Ice Supplies) Ltd. New ice plants were built in Lerwick and Scalloway. The company continued to trade under that name until it became part of L.H.D Marine Supplies Limited in April 2004. In 1994, the local company Oceansafe Ltd, which specialised in the production of nets for the salmon and fishing industries, was taken over. Together with its former manager, a new company Oceansafe (Shetland) Ltd, was formed on 5 September 1994. The company ceased trading in February 2004. Nets are now designed, manufactured and repaired by L.H.D Marine Supplies Limited. The company also specialises in the supply of ship chandlery, wire rope and chain, fishing gear, lifting gear and the supply of fuel oil.', 'https://oneshetland.com/business-logos/lhd-marine-supplies-ltd.png', 'livinglerwick', false, true),
  ('Lighthouse Counselling Shetland', 'other', 'Lerwick, Shetland', '07438 863736', null, 'Located at The Mission in Lerwick town centre, Lighthouse Counselling Shetland offers a safe, confidential and welcoming space where people can feel heard, supported and understood. Founded by Claire, a fully qualified person-centred counsellor, the service supports individuals experiencing stress, anxiety, relationship difficulties, life changes, grief and loss, with a specialist interest in bereavement and end-of-life support. With a gentle, client-led approach, Lighthouse Counselling Shetland provides a calm and private environment in the heart of Lerwick, easily accessible for people across Shetland. You can contact Claire via Facebook or by calling 07438 863736.', 'https://oneshetland.com/business-logos/lighthouse-counselling-shetland.jpg', 'livinglerwick', false, true),
  ('Loose Ends', 'retail', 'Lerwick, Shetland', '01595 696857', null, 'Loose Ends is an independent knitting, yarn and haberdashery shop in the centre of Lerwick''s Commercial Street. Selling everything from fabric to knitting patterns, wool, wool accessories, quilting fabric, haberdashery, and Shetland gifts. We pride ourselves on getting the best craft supplies and equipment quickly and at great affordable prices. "Loose Ends is on Commercial Street in Lerwick. The staff are really friendly and helpful, and they have a wonderful assortment of things you just won''t find anywhere else in Shetland! If you are a knitter or a sewer, you do not want to miss this little shop!"', 'https://oneshetland.com/business-logos/loose-ends.png', 'livinglerwick', false, true),
  ('Love From Shetland', 'retail', 'Lerwick, Shetland', null, null, 'We are a small family run company based in the Shetland Islands. All of our soaps and bath products are handmade by myself here in Shetland , using the best sourced natural ingredients including our very own Goats Milk. We have an amazing selection of soaps , including our skincare range of fragrance free, as well as our very popular Hand and Body Butters, Handfelted Shetland Wool Soap and a wide selection of handmade Gifts . Pop in along and you might be lucky enough to meet our very own Little Miss Goatee. We pride ourselves by not using any parabens or SLS&rsquo;s, we also care about the conservation of our planet and therefore you wont find Palm Oil in any of our products. We are proud to be the first business in Scotland to have achieved Palm Oil Free Certification for all of our products.', 'https://oneshetland.com/business-logos/shetland-with-love.jpeg', 'livinglerwick', false, true),
  ('Marine Scotland', 'other', 'Lerwick, Shetland', '01595 696926', null, 'Marine Scotland is responsible for the integrated management of Scotland''s seas. Its purpose is to manage Scotland''s seas for prosperity and environmental sustainability, working closely with our key delivery partners and others.', null, 'livinglerwick', false, true),
  ('Marine Scotland Science', 'other', 'Lerwick, Shetland', null, null, 'Marine Scotland Science (MSS), the scientific Division of Marine Scotland, plays an integral part in supporting the Scottish Government''s vision of marine and coastal environments that are clean, healthy, safe, productive, biologically diverse and are managed to meet the long-term needs of both nature and people.', 'https://oneshetland.com/business-logos/marine-scotland-science.jpg', 'livinglerwick', false, true),
  ('Meraki Hair Studio', 'services', 'Lerwick, Shetland', '07051086425', null, 'Located in the heart of Lerwick town centre, Meraki is a modern and welcoming hair salon offering professional hairdressing services. With a focus on creativity, care and attention to detail, the team at Meraki provides everything from precision cuts and colouring to styling for special occasions. Whether you''re looking for a fresh new look, a subtle refresh, or expert advice on maintaining healthy hair, you&rsquo;ll find a friendly and relaxed experience in this stylish town centre salon.', 'https://oneshetland.com/business-logos/meraki-hair-studio.jpg', 'livinglerwick', false, true),
  ('MH Apps', 'other', 'Lerwick, Shetland', '01595 708090', null, 'MH Apps develop high quality desktop, mobile and web solutions for a wide range of businesses to help reduce and simplify admin work, improve processes & productivity and enhance sales & marketing activities. We are also a supplier of Ingenico card machines and can offer excellent deals on terminals/merchant services through selected brokers, plus hold replacement terminals for same day swap-outs.', 'https://oneshetland.com/business-logos/mh-apps.png', 'livinglerwick', false, true),
  ('Michael Inkster & Co', 'services', 'Lerwick, Shetland', '01595 696901', null, 'Michael Inkster & Co Solicitors - Shetland Property for Sale or Let Michael Inkster and Co are a firm of solicitors based in Shetland, Shetland Isles. To contact Michael Inkster and Co, please call their phone number on 01595 696901. Address is as follows: Michael Inkster and Co, 159 Commercial Street, Lerwick, Shetland, Shetland Isles, ZE1 0EX.', 'https://oneshetland.com/business-logos/michael-inkster-co.jpg', 'livinglerwick', false, true),
  ('Michael Thomson FRICS', 'other', 'Lerwick, Shetland', '01595 695555', null, null, 'https://oneshetland.com/business-logos/michael-thomson-frics.jpg', 'livinglerwick', false, true),
  ('Monitor Station', 'other', 'Lerwick, Shetland', null, null, null, 'https://oneshetland.com/business-logos/monitor-station.jpg', 'livinglerwick', false, true),
  ('NB Communication Ltd', 'services', 'Lerwick, Shetland', '01595 696155', null, 'We are NB Communication, experts in digital strategy. Founded in the beautiful Shetland Islands, with a 2nd base in Edinburgh, we work for clients throughout the UK, and beyond. We can help you define your unique Digital Strategy that will give your Website and Marketing the focus it needs to succeed.', 'https://oneshetland.com/business-logos/nb-communication-ltd.jpg', 'livinglerwick', false, true),
  ('née gibson architects', 'services', 'Lerwick, Shetland', '01595 695000', null, 'We are a locally based Architects practice with extensive experience in all major sectors including housing, healthcare, local authority work, commercial, industrial and bespoke private houses. We strive to produce the best possible design solutions for our clients. Please visit our website for more information and examples of our work over the past 40+ years, and to the current day...', 'https://oneshetland.com/business-logos/richard-gibson-architects.jpg', 'livinglerwick', false, true),
  ('New Golden Coach', 'other', 'Lerwick, Shetland', '01595 693848', null, null, 'https://oneshetland.com/business-logos/new-golden-coach.png', 'livinglerwick', false, true),
  ('NGR Accountants', 'services', 'Lerwick, Shetland', '07158017158', null, 'NGR Accountancy was founded with a clear goal&mdash;to remove the stress and complexity of accounting for small businesses and self-employed professionals. After more than a decade working in a traditional accountancy practice, founder Neil recognized that many small businesses weren&rsquo;t getting the hands-on support they needed. With this in mind, NGR Accountancy was established to provide a client-focused approach, ensuring business owners can leave the numbers in expert hands and concentrate on running their businesses. The firm is built around a simple question: What do small business owners really need from their accountant? NGR Accountancy takes care of the financial details, so clients can focus on what matters most.', 'https://oneshetland.com/business-logos/ngr-accountants.jpg', 'livinglerwick', false, true),
  ('Ninian', 'services', 'Lerwick, Shetland', '01595 696655', null, 'Ninian specialises in design led Shetland knitwear which is designed and made in-store by Joanna Hunter and her team. Ask to have a look at the knitwear studio and see where and how they make there collections. To compliment the knitwear they stock a wide variety of design led gifts, many of which are British made. There''s a large selection of products from Local Shetland designers and artists, fine jewellery to hand built ceramics, there''s lots of exciting ideas for that perfect gift or just a treat for yourself.', 'https://oneshetland.com/business-logos/ninian.png', 'livinglerwick', false, true),
  ('No88 Kitchen & Bar Lerwick', 'services', 'Lerwick, Shetland', '01595 692139', null, 'At No88 we strive to use the best local seasonal produce to give you the best meal we can. We are in close contact with our suppliers all year round to make sure we only serve the best they have to offer. We would rather change our menu than use produce that is not up to the top standard. Shetland is famed for it sea food and meats and we intend to show them off to their best.', 'https://oneshetland.com/business-logos/no-88.png', 'livinglerwick', false, true),
  ('Nomadic Pizzeria Ltd', 'tourism', 'Lerwick, Shetland', null, null, 'Looking for proper, delicious pizza? This local favourite serves up freshly made pizzas packed with flavour, using quality ingredients. Whether you&rsquo;re after a classic Margherita, a meat-loaded feast, or something a little different, there&rsquo;s something for everyone on the menu. Perfect takeaway for a night in! With a warm welcome and a passion for great food, it&rsquo;s no wonder this pizzeria is a go-to spot for both locals and visitors. Pop in and see what&rsquo;s cooking &ndash; you might just find your new favourite pizza place!', 'https://oneshetland.com/business-logos/nomadic-pizzeria-ltd.jpg', 'livinglerwick', false, true),
  ('Outdoor4kids/Outdoor Trek', 'accommodation', 'Lerwick, Shetland', '01595 695111', null, 'Selling camping equipment and adult & kids outdoor clothing from well known brands like Berghaus, Rab, Jack Wolfskin and many more. Online and telephone orders also welcome.', 'https://oneshetland.com/business-logos/outdoor4kids-outdoor-trek.jpg', 'livinglerwick', false, true),
  ('Parliamentary Office', 'other', 'Lerwick, Shetland', '01595 690044', null, 'MSP''s can be contacted via email: alistair.carmichael.mp@parliament.uk/Beatrice.wishart.msp@parliament.scot', 'https://oneshetland.com/business-logos/parliamentary-office.jpg', 'livinglerwick', false, true),
  ('Peerie Isles', 'retail', 'Lerwick, Shetland', '01595 693202', null, 'Shetland crafters and UK crafters bringing all their unique handcrafted pieces to you from one place - Peerie Isles shop, Lerwick. Find that perfect gift or a peerie treat for yourself. Gift vouchers available', 'https://oneshetland.com/business-logos/peerie-isles.png', 'livinglerwick', false, true),
  ('Peerie Shop', 'services', 'Lerwick, Shetland', '01595 692816', null, 'The Peerie Shop ''theonestoppresentshop'', in front of the Peerie Shop Caf&eacute; on the Esplanade. A huge range of carefully chosen colourful interesting gifts from around the world. Fair trade, ethically sourced, British, and produced by us. Victoria Gibson hand-knitted designer knitwear and its own range of Shetland t-shirts, postcards, bags, fridge magnets and badges. A good selection of books, bowls, decorations, scarves, jewellery, cards, candles, boxes and glasses.', 'https://oneshetland.com/business-logos/peerie-shop.png', 'livinglerwick', false, true),
  ('Peerie Shop Cafe', 'food_drink', 'Lerwick, Shetland', '01595 692817', null, 'We make everything ourselves using local and seasonal produce whenever possible.. Striving for the best coffee, roasted every month for us in Perth. Lots of tempting in house baking, pastries and cakes, tray bakes, tarts and savoury pies. Breakfast served until 11am and then a lunchtime menu. Gluten free, vegan and vegetarian. Changing daily menu. Lots of local flavours. Take away, inside seating and outside tables, in the summer. Plastic free. Compostable packaging. Free wifi. Local Art, Follow us on social media for specail events. Donut days and saturday brunch', 'https://oneshetland.com/business-logos/peerie-shop-cafe.jpeg', 'livinglerwick', false, true),
  ('Pete''s Cafe and Takeaway', 'food_drink', 'Lerwick, Shetland', '07199999999', null, 'Caf&eacute; offering breakfast and lunch in the historic Solotti''s & Faerdie Maet premises. Check out Pete''s Facebook page for daily specials', 'https://oneshetland.com/business-logos/petes-cafe-and-takeaway.jpg', 'livinglerwick', false, true),
  ('Public Convenience', 'other', 'Lerwick, Shetland', null, null, 'From Monday 7th June 2022, the opening hours of the public toilets at Harbour House in Lerwick are to be extended, to open from 8am to 9pm daily, seven days a week. Shower facilities at the same location are also being re-opened, since closing at the start of the pandemic. Users are asked to bring their own towels if possible, although towels will available to hire, which will be quarantined for 48 hours before being washed.', 'https://oneshetland.com/business-logos/public-convenience.jpg', 'livinglerwick', false, true),
  ('Puffin Rebublic', 'other', 'Lerwick, Shetland', '07046586031', null, null, 'https://oneshetland.com/business-logos/la-annexe.jpg', 'livinglerwick', false, true),
  ('R. Robertson & Son Ltd', 'services', 'Lerwick, Shetland', '07525634765', null, 'R. Robertson & Son Ltd are Shetland&rsquo;s largest transport operator, based in the main town of Lerwick. Providing private hires and tours within Shetland and the UK Mainland, for both national and international travel agencies, as well as local customers. Small groups from two people to hundreds of people can be catered for, along with bespoke tours and itineraries. Operations include private hire taxis, public service and home to school transport. The Lerwick workshop does contract maintenance for fleet customers as well as in house maintenance.', 'https://oneshetland.com/business-logos/r-robertson-son-ltd.jpg', 'livinglerwick', false, true),
  ('R.A.M Knitwear', 'services', 'Lerwick, Shetland', '07890 160464', null, 'Unique and attractive knitwear designs by Roisin McAtamney. A fun and fresh custom knitwear design company. Creating unique fashion and promoting the versatility of knitting craftsmanship.', 'https://oneshetland.com/business-logos/r.a.m-knitwear.png', 'livinglerwick', false, true),
  ('Radiance Shetland Ltd', 'services', 'Lerwick, Shetland', '07458242314', null, 'Radiance Shetland &ndash; Your One-Stop Beauty Destination Originally starting as a tanning salon, Radiance Shetland has grown into a full-service beauty hub offering expert hair, nail, and beauty treatments. We are thrilled to be the first in Shetland to introduce permanent jewelry &ndash; a unique and stylish way to symbolize lasting bonds between friends, family, or couples. From sunbed sessions to cutting-edge hair styling and manicures, Radiance is your go-to destination for all things beauty. We look forward to welcoming you and helping you look and feel your best! Services include professional hair dressing, sunbed sessions for that perfect glow, and beauty treatments tailored to your needs. Radiance Shetland also offers the latest trend in permanent jewellery, where you can get custom-fitted bracelets and anklets that last. Visit Radiance Shetland for a full pampering experience, combining beauty, style, and luxury all in one place.', 'https://oneshetland.com/business-logos/radiance-shetland-ltd.jpg', 'livinglerwick', false, true),
  ('Realta Events Management', 'other', 'Lerwick, Shetland', '07753 806095', null, 'Realta Events Management offers bespoke event and project management services to the public and private sector.', 'https://oneshetland.com/business-logos/realta-events-management.jpg', 'livinglerwick', false, true),
  ('Reset Well-being Therapies', 'services', 'Lerwick, Shetland', null, null, 'Reset Wellbeing Therapies is founded by Jennie, whose lifelong passion for caring spans nursing, social care, dementia support, oncology massage and over 30 years practising Reiki. With a career rooted in holistic, compassionate support, Jennie brings together clinical experience and spiritual awareness to care for the whole person &mdash; emotionally, physically and socially. Based at The Mission on Harbour Street in Lerwick town centre, Reset Wellbeing Therapies offers a wide range of tailored treatments including deep tissue and pregnancy massage, oncology massage, hot stone and Ayurvedic therapies, Reiki, reflexology, lymphatic drainage and bespoke self-care packages. Each session is personalised, reflecting Jennie&rsquo;s belief that wellbeing is never one-size-fits-all. Room 7, The Mission &ndash; Creativity & Wellness Centre, 2 Harbour Street, Lerwick, ZE1 0LR', 'https://oneshetland.com/business-logos/reset-wellbeing-therapies.jpg', 'livinglerwick', false, true),
  ('Royal Mail', 'other', 'Lerwick, Shetland', null, null, null, 'https://oneshetland.com/business-logos/royal-mail.jpg', 'livinglerwick', false, true),
  ('RSM', 'services', 'Lerwick, Shetland', '01595 743520', null, 'RSM are an independent firm of accountants and business advisers. We provide a wide range of services including tax and financial planning as well as accountancy and audit.', 'https://oneshetland.com/business-logos/rsm.jpg', 'livinglerwick', false, true),
  ('Santander UK Plc', 'other', 'Lerwick, Shetland', null, null, null, null, 'livinglerwick', false, true),
  ('Scottish Children''s Report Administration', 'other', 'Lerwick, Shetland', null, null, 'Opening times This office is open during the following times: Monday - Thursday 09:00 - 17:00 Friday 09:00 - 16:00 This office is closed on the following public holidays: Wednesday 1 January 2025 Thursday 2 January 2025 Friday 18 April 2025 Monday 21 April 2025 Monday 5 May 2025 Monday 1 December 2025 Thursday 25 December 2025 Friday 26 December 2025', 'https://oneshetland.com/business-logos/scottish-childrens-report-administration.jpg', 'livinglerwick', false, true),
  ('Scottish Fisheries Protection Agency', 'other', 'Lerwick, Shetland', '01595 692007', null, null, 'https://oneshetland.com/business-logos/scottish-fisheries-protection-agency.jpg', 'livinglerwick', false, true),
  ('Shetland Aerogenerators Ltd', 'other', 'Lerwick, Shetland', '01595 690900', null, 'Shetland Aerogenerators was formed in 1992, and we operate from our offices on Charlotte Street in Shetland&rsquo;s capital of Lerwick. We initially set out to investigate the opportunities expected after the Government announced the Scottish Renewables Obligation. Shetland Aerogenerators owns Burradale Windfarm and we have acted as developer, constructor, operator and client at various stages.', 'https://oneshetland.com/business-logos/shetland-aerogenerators-ltd.jpg', 'livinglerwick', false, true),
  ('Shetland Bookshop', 'services', 'Lerwick, Shetland', '01595 695531', null, 'The Shetland Bookshop is a general bookshop with a large Shetland interest section. We offer a customer ordering service for any in-print titles we do not have on our shelves. We also stock a wide range of adult and children''s gifts, cards and wrap, stationery, souvenirs and maps.', 'https://oneshetland.com/business-logos/shetland-times-bookshop.png', 'livinglerwick', false, true),
  ('Shetland Broadband LLP', 'other', 'Lerwick, Shetland', '01595 696297', null, null, 'https://oneshetland.com/business-logos/shetland-broadband-llp.jpg', 'livinglerwick', false, true),
  ('Shetland Fish', 'other', 'Lerwick, Shetland', '07048583938', null, 'Shetland Fish Ltd is at the forefront of an exciting time for the Shetland fishing industry. Shetland&rsquo;s fishing industry is undergoing a renaissance. The fleet is modernising to take advantage of the healthy, sustainable fish stocks which gather around Shetland&rsquo;s wild coast. Four of our main stocks haddock, coley, hake and plaice still hold MSC status and our onshore infrastructure is improving with two new fish markets currently being built. The Shetland Islands is located in the midst of some of the most prolific fishing grounds in Europe. Shetland is the second largest whitefish landing port in the UK. Our buying team is dedicated to helping our customers access some of the finest, freshest whitefish available. We are passionate about the high quality of seafood landed in Shetland, and we are proud to play our part in connecting buyers from all over the UK and Europe with this outstanding source of fresh fish. If you would like to become a valued partner in Shetland fish, please contact us.', 'https://oneshetland.com/business-logos/shetland-fish.png', 'livinglerwick', false, true),
  ('Shetland Property Lets', 'other', 'Lerwick, Shetland', '01595 692033', null, null, 'https://oneshetland.com/business-logos/shetland-property-lets.jpg', 'livinglerwick', false, true),
  ('Shetland Soap Company', 'retail', 'Lerwick, Shetland', '01595 696889', null, 'Here at the Shetland Soap Company, our soap and skincare range is inspired by the islands'' raw elements, and are hand crafted using both traditional and contemporary methods to combine the very best natural ingredients. Added to that, all our products are handmade by people who really care about what they do. People with learning disabilities that are extremely proud of the work they do. Incredible products from incredible people. Shetland Soap Company is proudly part of COPE Ltd, one of Scotland&rsquo;s leading social enterprises, providing employment and employment skill development for adults with disabilities. Find out more about COPE Ltd at www.cope.ltd.co.uk To see our range of products or to buy online visit www.shetlandsoap.co.uk', 'https://oneshetland.com/business-logos/shetland-soap-co-ltd.png', 'livinglerwick', false, true),
  ('Shetland Somatic Arts', 'services', 'Lerwick, Shetland', '07448196411', null, 'Located in the centre of Lerwick, Shetland Somatic Arts is a modern, welcoming tattoo and piercing studio known for its creativity, professionalism, and attention to detail. This unique self-care studio offers a diverse range of services, bringing together a collective of experienced practitioners to create a welcoming and holistic environment. The space is home to Lymfastr&ouml;m Therapy, offering both manual lymphatic drainage and Swedish massage. Lymphatic massage is particularly beneficial for post-surgical recovery and for individuals undergoing cancer treatments. From next month, The Brow Arc. Co will also be joining the studio, providing a range of brow and beauty treatments. In addition, Jody Does Jels and Education delivers accredited gel nail courses throughout the week. At the heart of the studio is an experienced tattoo artist and body piercer, specialising in the hand-poked, machine-free tattoo method. With piercing experience since 2012 and tattooing since 2013, their work is grounded in both skill and care. Alongside their creative practice, they are currently in their final year of counselling studies at UHI, bringing an added depth of understanding to their approach. This combination of experience allows the studio to offer a truly person-centred, body-led, and trauma-informed service. Each client is treated holistically, with respect for their personal history, nervous system, and individual responses. Rather than rushing procedures, clients are given the time and space they need to feel comfortable, process their experience, and fully engage with the experience. Recognising that tattoos and piercings often hold deep personal meaning, the studio supports clients in marking significant moments in their lives&mdash;whether beginnings, transitions, or endings. Client autonomy and informed consent are central to every aspect of the service, creating a safe, respectful, and empowering environment for all. Please remember that all services are by appointment only, and it&rsquo;s important to bring an acceptable form of photo ID to access our services. Here&rsquo;s what you can bring: &bull; Passport &bull; Driver''s License &bull; Provisional License &bull; Young Scot Card For younger clients (under 16 years), they kindly ask that a legal parent is present. You&rsquo;ll also need to bring: &bull; Consent and photo ID from the other legal parent (if they are not attending) &bull; Full Birth Certificate &bull; Young Scot Card &bull; A form of photo ID for the attending legal parent from the list above If you have any questions or need further assistance, please don&rsquo;t hesitate to send them an email or message, and a member of their caring team will respond as soon as possible.', 'https://oneshetland.com/business-logos/shetland-somatic-arts.jpg', 'livinglerwick', false, true),
  ('Shetland Telecom', 'services', 'Lerwick, Shetland', '01595 745678', null, 'Shetland Islands Council has identified improving data communication services across the Isles as one of its key targets. To help meet this aspiration the SIC has set up the Shetland Telecom Project. Its remit is to improve data communications. The Shetland Telecom Project was established in 2009 to undertake a significant step change in telecoms provision in Shetland. The project has successfully achieved the provision of resilient, reliable, high capacity data services for Shetland. The project is part of Shetland Islands Council&rsquo;s Economic Development Unit. The fibre optic network which it now manages was part funded by the EU. The Shetland Telecom Project is a member of the Internet Service Providers Association (ISPA) and the Independent Network Cooperative Association (INCA).', 'https://oneshetland.com/business-logos/shetland-telecom.jpg', 'livinglerwick', false, true),
  ('Shetland Wool Adventures', 'services', 'Lerwick, Shetland', null, null, 'Specialist knitting tours in Shetland & Shetland Wool Adventures Journal. Join us on a unforgettable journey to discover Shetland and our unique textile heritage. Our tours are designed to give you an insight into Shetland''s knitting traditions and local textile industry. ​The trips provide local knowledge and history as well as excellent learning opportunities in knitting from local expert tutors.', 'https://oneshetland.com/business-logos/shetland-wool-adventures.png', 'livinglerwick', false, true),
  ('SIBC: Shetland Islands Broadcasting Company Limited', 'other', 'Lerwick, Shetland', '01595 695299', null, 'Commercial radio station broadcasting 24 hours a day, 365/6 days of the year.', 'https://oneshetland.com/business-logos/sibc-ltd.jpg', 'livinglerwick', false, true),
  ('SIC Town Hall', 'other', 'Lerwick, Shetland', '01595 693535', null, null, 'https://oneshetland.com/business-logos/sic-town-hall.jpg', 'livinglerwick', false, true),
  ('Smith & Robertson', 'retail', 'Lerwick, Shetland', '01595 693627', null, 'Smith and Robertson stocks a wide range of ladies fashion and accessories, as well as a selection of menswear. The store has a long history on Commercial Street and celebrates it''s 125th anniversary in 2019. Personal shopping times can be arranged on request. The new Facebook page will publish a regular update of images for new and classic styles available.', 'https://oneshetland.com/business-logos/smith-robertson.png', 'livinglerwick', false, true),
